using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.JNT.JuntaDetalleArchivos;using GraphApi.Services.JNT.JuntaDetalleArchivos;namespace GraphApi.Controllers.JNT.JuntaDetalleArchivos{    /// <summary>    /// Gestión de JuntaDetalleArchivos: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("JNT/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre JuntaDetalleArchivos")]    public class JuntaDetalleArchivosController : Controller    {        private readonly IJuntaDetalleArchivosService _objService;        public JuntaDetalleArchivosController(IJuntaDetalleArchivosService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los JuntaDetalleArchivos, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="juntaDetalleArchivoID">JuntaDetalleArchivoID</param>        /// <param name="juntaDetalleID">JuntaDetalleID</param>        /// <param name="nombreArchivo">NombreArchivo</param>        /// <param name="ruta">Ruta</param>        /// <param name="tipoArchivo">TipoArchivo</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de JuntaDetalleArchivos</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar JuntaDetalleArchivos",            Description = "Devuelve JuntaDetalleArchivos aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadJuntaDetalleArchivos>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadJuntaDetalleArchivos>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? juntaDetalleArchivoID,            [FromQuery] int? juntaDetalleID,            [FromQuery] string? nombreArchivo,            [FromQuery] string? ruta,            [FromQuery] string? tipoArchivo,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetJuntaDetalleArchivosDynamic(                juntaDetalleArchivoID,                 juntaDetalleID,                 nombreArchivo,                 ruta,                 tipoArchivo,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo JuntaDetalleArchivo.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del JuntaDetalleArchivo a crear.</param>        /// <returns>El JuntaDetalleArchivo recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear JuntaDetalleArchivos",            Description = "Inserta un nuevo JuntaDetalleArchivo en la base de datos."        )]        [ProducesResponseType(typeof(clReadJuntaDetalleArchivos), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadJuntaDetalleArchivos>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateJuntaDetalleArchivos objInput)        {            var vCreated = await _objService.CreateJuntaDetalleArchivos(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de JuntaDetalleArchivo.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del JuntaDetalleArchivo.</param>        /// <returns>El JuntaDetalleArchivo actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar JuntaDetalleArchivos",            Description = "Actualiza uno o varios campos de JuntaDetalleArchivo existente."        )]        [ProducesResponseType(typeof(clReadJuntaDetalleArchivos), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadJuntaDetalleArchivos>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateJuntaDetalleArchivos objInput)        {            var vUpdated = await _objService.UpdateJuntaDetalleArchivos(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un JuntaDetalleArchivo por su ID.        /// </summary>        [HttpDelete("{nJuntaDetalleArchivosID:int}")]        [SwaggerOperation(            Summary = "Eliminar JuntaDetalleArchivo",            Description = "Borra un JuntaDetalleArchivo si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nJuntaDetalleArchivosID)        {            var success = await _objService.DeleteJuntaDetalleArchivos(nJuntaDetalleArchivosID);            return success ? NoContent() : NotFound();        }    }}